/**
 * Official Angelini Full Brand Logo
 * Renders the 100% exact vector logo provided by the user (ANGELINI Inmobiliaria + Bull emblem)
 */
export const Logo: React.FC<LogoProps> = ({
  className = '',
  variant = 'dark',
  size = 'md',
  showEmblem = true,
  showSlogan = false,
  layout = 'horizontal',
  alt = 'Angelini Inmobiliaria',
}) => {
  const isLight = variant === 'light';

  // Responsive size heights (+15% larger)
  const sizeMap = {
    sm: 'h-9 sm:h-10.5 max-w-[195px]',
    md: 'h-11.5 sm:h-14 max-w-[255px]',
    lg: 'h-16 sm:h-18 max-w-[345px]',
    xl: 'h-24 sm:h-28 max-w-[485px]',
  };

  const getSrc = () => {
    if (variant === 'light') return '/angelini-logo-white.svg';
    if (variant === 'scrolled') return '/angelini-logo-color-white-text.svg';
    return '/angelini-logo-color.svg';
  };
  const src = getSrc();

  return (
    <div
      className={`inline-flex items-center select-none ${
        layout === 'vertical' ? 'flex-col justify-center text-center' : ''
      } ${className}`}
    >
      <img
        src={src}
        alt={alt}
        className={`w-auto ${sizeMap[size]} object-contain`}
        draggable={false}
      />
    </div>
  );
};
